import axios from 'axios';

export const getAllOrders = token => {
	return dispatch => {
		const config = {
			headers: {
				authorization: `Bearer ${token}`,
			},
		};

		axios
			.get(`${process.env.REACT_APP_ENITURE_API_URL}/get_orders`, config)
			.then(({ data }) => {
				dispatch({
					type: 'GET_ORDERS',
					payload: data?.data?.allOrders,
				});
			})
			.catch(err => {
				dispatch({
					type: 'GET_ORDERS',
					payload: [],
				});
			});
	};
};

export const getOrderDetail = (id, setselectedOrderDetail, setLoadOrder, token) => {
	
	return dispatch => {
		axios
		.get(`${process.env.REACT_APP_ENITURE_API_URL}/get_order_widget`, {
			headers: {
				authorization: `Bearer ${token}`,
			},
			params: {
				order_id: id,
			},
		})
		.then(({ data }) => {
			if (!data.error) {
				dispatch({
					type: 'GET_ORDER_WIDGET',
					payload: data?.data
				});
				//setselectedOrderDetail(orderDetail);
				setLoadOrder(false);
			}
		});
	}
};

export const submitOrderSettings = (orderSettings, token, setState) => {
	return dispatch => {
		dispatch({
			type: 'ALERT_MESSAGE',
			payload: {
				showAlertMessage: true,
				alertMessageType: 'loading',
			},
		});

		axios
			.post(`${process.env.REACT_APP_ENITURE_API_URL}/update_order`, orderSettings, {
				headers: {
					authorization: `Bearer ${token}`,
				},
			})
			.then(({ data }) => {
				if (!data.error) {
					dispatch({
						type: 'UPDATE_ORDER_SETTINGS',
						payload: data.data,
					});

					setState(ps => ({
						...ps,
						visible: false,
					}));
				}

				dispatch({
					type: 'ALERT_MESSAGE',
					payload: {
						alertMessage: data.message,
						showAlertMessage: true,
						alertMessageType: data.error ? 'error' : 'success',
					},
				});
			})
			.catch(error => {});
	};
};
